 "content": "def transform(grid):
    """Draw an outward rectangular spiral from the 3, leaving 2s unchanged."""
    out = [row[:] for row in grid]
    n, m = len(grid), len(grid[0])
    start = next(((r, c) for r in range(n) for c in range(m) if grid[r][c] == 3), None)
    if start is None:
        return out
    r, c = start
    directions = [(-1, 0), (0, 1), (1, 0), (0, -1)]
    length, d = 2, 0
    while True:
        for _ in range(2):
            dr, dc = directions[d]
            for _ in range(length):
                r += dr
